package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"os/exec"
	"strings"
	"time"
)

var webhookSecret = os.Getenv("WEBHOOK_SECRET")

type PipelineJob struct {
	RepoURL    string      `json:"repo_url"`
	Branch     string      `json:"branch"`
	CommitSHA  string      `json:"commit_sha"`
	BuildSteps []BuildStep `json:"build_steps"`
}

type BuildStep struct {
	Name    string            `json:"name"`
	Command string            `json:"command"`
	Args    []string          `json:"args"`
	Env     map[string]string `json:"env"`
}

func verifySignature(payload []byte, signature string) bool {
	mac := hmac.New(sha256.New, []byte(webhookSecret))
	mac.Write(payload)
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(signature))
}

func extractClientIP(r *http.Request) string {
	return r.RemoteAddr
}

func isInternalRequest(r *http.Request) bool {
	clientIP := extractClientIP(r)
	return strings.HasPrefix(clientIP, "10.") ||
		strings.HasPrefix(clientIP, "172.16.") ||
		strings.HasPrefix(clientIP, "192.168.")
}

func sanitizeBuildStep(step BuildStep) error {
	allowedCommands := map[string]bool{
		"go":     true,
		"make":   true,
		"docker": true,
		"npm":    true,
		"yarn":   true,
	}
	if !allowedCommands[step.Command] {
		return fmt.Errorf("command %q not in allowlist", step.Command)
	}
	for _, arg := range step.Args {
		if strings.ContainsAny(arg, ";|&`$") {
			return fmt.Errorf("argument %q contains forbidden characters", arg)
		}
	}
	return nil
}

func executePipeline(job PipelineJob) error {
	log.Printf("Executing pipeline for %s@%s (%s)", job.RepoURL, job.Branch, job.CommitSHA)
	for _, step := range job.BuildSteps {
		if err := sanitizeBuildStep(step); err != nil {
			return err
		}
		cmd := exec.Command(step.Command, step.Args...)
		for k, v := range step.Env {
			if strings.ContainsAny(k, "=") || strings.ContainsAny(v, "\x00") {
				return fmt.Errorf("invalid env var: %s", k)
			}
			cmd.Env = append(cmd.Env, fmt.Sprintf("%s=%s", k, v))
		}
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			return fmt.Errorf("step %q failed: %w", step.Name, err)
		}
	}
	return nil
}

func handleWebhook(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		http.Error(w, "read error", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	signature := r.Header.Get("X-Hub-Signature-256")
	if signature == "" || !verifySignature(body, signature) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	contentType := r.Header.Get("Content-Type")
	var job PipelineJob

	switch {
	case strings.Contains(contentType, "application/json"):
		dec := json.NewDecoder(bytes.NewReader(body))
		dec.DisallowUnknownFields()
		if err := dec.Decode(&job); err != nil {
			http.Error(w, "decode error", http.StatusBadRequest)
			return
		}
	default:
		http.Error(w, "unsupported content type", http.StatusUnsupportedMediaType)
		return
	}

	go func() {
		if err := executePipeline(job); err != nil {
			log.Printf("Pipeline failed: %v", err)
		}
	}()

	w.WriteHeader(http.StatusAccepted)
	fmt.Fprintf(w, "pipeline queued for %s", job.CommitSHA)
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	fmt.Fprint(w, "ok")
}

func main() {
	if webhookSecret == "" {
		log.Fatal("WEBHOOK_SECRET environment variable required")
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/webhook", handleWebhook)
	mux.HandleFunc("/health", handleHealth)

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadTimeout:       15 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	log.Println("CI/CD agent listening on :8080")
	log.Fatal(srv.ListenAndServe())
}
